"""Request-ID and fixed-window rate-limit middleware."""

from __future__ import annotations

import math
import time
import uuid

from fastapi import Request, Response
from fastapi.responses import JSONResponse
from starlette.middleware.base import BaseHTTPMiddleware, RequestResponseEndpoint
from starlette.types import ASGIApp

from daily_signal.api.schemas.errors import ApiError, ApiErrorBody

_WINDOW_SECONDS = 60.0
_JSON_MEDIA_TYPE = "application/json"

#: Fallback codes for non-JSON 4xx responses generated by middleware that never
#: reach the application's exception handlers — most notably a rejected CORS
#: preflight, which Starlette answers directly with a plain-text 400.
_MIDDLEWARE_4XX_CODES: dict[int, str] = {
    400: "bad_request",
    401: "unauthorized",
    403: "forbidden",
    404: "not_found",
    405: "method_not_allowed",
    409: "conflict",
    422: "invalid_parameter",
    429: "rate_limited",
}


def _is_json_response(response: Response) -> bool:
    """Return whether ``response`` already carries a JSON content type."""
    content_type = response.headers.get("content-type", "")
    return content_type.split(";", 1)[0].strip().lower() == _JSON_MEDIA_TYPE


async def _normalize_client_error(request: Request, response: Response) -> Response:
    """Rewrite a middleware-generated non-JSON 4xx as the standard envelope.

    The original response (e.g. ``Disallowed CORS origin`` plain text) is
    drained and discarded. Protocol headers such as ``Allow`` or the CORS
    headers are preserved; the content type and length are replaced with the
    JSON envelope's own.
    """
    body_iterator = getattr(response, "body_iterator", None)
    if body_iterator is not None:
        async for _ in body_iterator:
            pass

    code = _MIDDLEWARE_4XX_CODES.get(response.status_code, "error")
    envelope = ApiError(
        error=ApiErrorBody(
            code=code,
            message="Request rejected.",
            request_id=request.state.request_id,
        )
    )
    normalized = JSONResponse(
        status_code=response.status_code,
        content=envelope.model_dump(by_alias=True),
    )
    for name, value in response.headers.items():
        if name.lower() in {"content-length", "content-type"}:
            continue
        normalized.headers.setdefault(name, value)
    return normalized


class RequestIdMiddleware(BaseHTTPMiddleware):
    """Assign a UUID4 to ``request.state.request_id`` and return ``X-Request-ID``.

    This middleware is registered outermost so that every response — including
    CORS preflights answered by ``CORSMiddleware`` and error envelopes produced
    by other middleware — carries the header. Any non-JSON 4xx response that
    bypassed the application's exception handlers is normalised to the standard
    error envelope so clients never receive a plain-text error.
    """

    async def dispatch(self, request: Request, call_next: RequestResponseEndpoint) -> Response:
        request.state.request_id = str(uuid.uuid4())
        response = await call_next(request)
        if 400 <= response.status_code < 500 and not _is_json_response(response):
            response = await _normalize_client_error(request, response)
        response.headers["X-Request-ID"] = request.state.request_id
        return response


class RateLimitMiddleware(BaseHTTPMiddleware):
    """In-memory fixed-window limiter for ``/v1/`` routes only.

    ``rate_limit_per_minute`` of ``0`` disables limiting. Each client host gets
    its own 60-second window (the ephemeral source port is ignored so a client
    cannot reset its allowance by opening a new connection); once exhausted,
    requests are rejected with a ``429`` envelope and a ``Retry-After`` header.
    Expired windows are purged periodically to bound memory use.
    """

    def __init__(self, app: ASGIApp, rate_limit_per_minute: int) -> None:
        super().__init__(app)
        self._limit = rate_limit_per_minute
        self._windows: dict[str, tuple[float, int]] = {}
        self._last_purge = 0.0

    async def dispatch(self, request: Request, call_next: RequestResponseEndpoint) -> Response:
        if self._limit <= 0:
            return await call_next(request)
        if not request.url.path.startswith("/v1/"):
            return await call_next(request)

        key = self._client_key(request)
        now = time.monotonic()
        self._maybe_purge(now)
        window_start, count = self._windows.get(key, (now, 0))
        if now - window_start >= _WINDOW_SECONDS:
            window_start = now
            count = 0
        if count >= self._limit:
            return self._rate_limited(request, window_start, now)
        self._windows[key] = (window_start, count + 1)
        return await call_next(request)

    @staticmethod
    def _client_key(request: Request) -> str:
        if request.client is None:
            return "unknown"
        return request.client.host

    def _maybe_purge(self, now: float) -> None:
        """Drop expired windows at most once per window to bound memory use."""
        if now - self._last_purge < _WINDOW_SECONDS:
            return
        self._last_purge = now
        self._purge_expired(now)

    def _purge_expired(self, now: float) -> None:
        expired = [
            key
            for key, (window_start, _) in self._windows.items()
            if now - window_start >= _WINDOW_SECONDS
        ]
        for key in expired:
            del self._windows[key]

    def _rate_limited(self, request: Request, window_start: float, now: float) -> JSONResponse:
        remaining = window_start + _WINDOW_SECONDS - now
        retry_after = max(1, math.ceil(remaining))
        body = ApiErrorBody(
            code="rate_limited",
            message="Rate limit exceeded.",
            request_id=request.state.request_id,
        )
        response = JSONResponse(
            status_code=429,
            content=ApiError(error=body).model_dump(by_alias=True),
        )
        response.headers["Retry-After"] = str(retry_after)
        return response
